package android.graphics;import java.awt.geom.*;public class Matrix {public AffineTransform transform=new AffineTransform();public boolean setPolyToPoly(float[] s,int so,float[] d,int at,int count){double sx=s[so],sy=s[so+1],tx=s[so+2],ty=s[so+3],ux=s[so+4],uy=s[so+5];double det=(tx-sx)*(uy-sy)-(ux-sx)*(ty-sy);if(Math.abs(det)<.000001)return false;double a=((d[at+2]-d[at])*(uy-sy)-(d[at+4]-d[at])*(ty-sy))/det,b=((d[at+4]-d[at])*(tx-sx)-(d[at+2]-d[at])*(ux-sx))/det,c=((d[at+3]-d[at+1])*(uy-sy)-(d[at+5]-d[at+1])*(ty-sy))/det,e=((d[at+5]-d[at+1])*(tx-sx)-(d[at+3]-d[at+1])*(ux-sx))/det;transform=new AffineTransform(a,c,b,e,d[at]-a*sx-b*sy,d[at+1]-c*sx-e*sy);return true;}public static final int MSCALE_X=0,MSKEW_X=1,MTRANS_X=2,MSKEW_Y=3,MSCALE_Y=4,MTRANS_Y=5;public enum ScaleToFit{FILL}public void setRectToRect(RectF a,RectF b,ScaleToFit mode){transform=new AffineTransform();transform.translate(b.left,b.top);transform.scale((b.right-b.left)/(a.right-a.left),(b.bottom-b.top)/(a.bottom-a.top));transform.translate(-a.left,-a.top);}public void postTranslate(float x,float y){transform.preConcatenate(AffineTransform.getTranslateInstance(x,y));}public void postConcat(Matrix other){transform.preConcatenate(other.transform);}public void set(Matrix m){transform=new AffineTransform(m.transform);}public void getValues(float[] values){double[] m=new double[6];transform.getMatrix(m);values[0]=(float)m[0];values[1]=(float)m[2];values[2]=(float)m[4];values[3]=(float)m[1];values[4]=(float)m[3];values[5]=(float)m[5];values[6]=values[7]=0;values[8]=1;}public void mapPoints(float[] p){transform.transform(p,0,p,0,p.length/2);}public boolean invert(Matrix inverse){try{inverse.transform=transform.createInverse();return true;}catch(NoninvertibleTransformException e){return false;}}}
